import{_ as r}from"./chunks/46.C5W596UJ.js";import{_ as s}from"./chunks/1._Wu06lVH.js";import{_ as i}from"./chunks/0.xVPDiwtD.js";import{_ as l}from"./chunks/2.9ug2zROR.js";import{_ as d}from"./chunks/1.BU1qyW7B.js";import{_ as o}from"./chunks/0.DyB7G7H5.js";import{_ as c}from"./chunks/4.ZpmvUIOM.js";import{_ as h}from"./chunks/1.ak2rshaV.js";import{_ as t}from"./chunks/0.C_OEUMPL.js";import{_ as m}from"./chunks/5.BkY6Rw8O.js";import{_ as p}from"./chunks/8.DS_jDXFp.js";import{_ as g}from"./chunks/100.DMbJtyMU.js";import{_ as u}from"./chunks/community.BdKwbEUF.js";import{_ as y,C as _,o as b,c as f,ak as n,E as w}from"./chunks/framework.sbZkgmEx.js";const v="/projects/AiBlock/en/advanced-kit/assets/1.DEYqyzbY.webp",x="/projects/AiBlock/en/advanced-kit/assets/2.CsRwh8A0.webp",k="/projects/AiBlock/en/advanced-kit/assets/2.2.B-zWBZGO.webp",P="/projects/AiBlock/en/advanced-kit/assets/3.DMC913s9.webp",z="/projects/AiBlock/en/advanced-kit/assets/4.t3d-FA66.webp",M=JSON.parse('{"title":"3.46 Thrill Pendulum Ride","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.46 Thrill Pendulum Ride.md","filePath":"docs/3.Creative Builds/3.46 Thrill Pendulum Ride.md"}'),q={name:"docs/3.Creative Builds/3.46 Thrill Pendulum Ride.md"};function T(A,e,C,j,S,B){const a=_("Pdf");return b(),f("div",null,[e[0]||(e[0]=n('<h1 id="_3-46-thrill-pendulum-ride" tabindex="-1">3.46 Thrill Pendulum Ride <a class="header-anchor" href="#_3-46-thrill-pendulum-ride" aria-label="Permalink to &quot;3.46 Thrill Pendulum Ride&quot;">​</a></h1><h2 id="_3-46-1-lesson-introduction" tabindex="-1">3.46.1 Lesson Introduction <a class="header-anchor" href="#_3-46-1-lesson-introduction" aria-label="Permalink to &quot;3.46.1 Lesson Introduction&quot;">​</a></h2><p>Focusing on a compound-motion giant pendulum ride model, this lesson explores coordinated programming among dual servos, a motor, and audiovisual modules. It achieves an immersive amusement park attraction featuring concurrent swinging and self-rotation, complemented by alternating lighting effects. The content illustrates compound gear transmission mechanics alongside dual-servo synchronized control methods. It applies mechanical regulation logic for composite motion. Furthermore, it examines core engineering design concepts combining multi-degree-of-freedom kinematics with atmospheric sensory feedback in amusement rides.</p><img loading="lazy" height="1662" width="1662" src="'+r+'" class="common_img" style="width:400px;"><h2 id="_3-46-2-learning-objectives" tabindex="-1">3.46.2 Learning Objectives <a class="header-anchor" href="#_3-46-2-learning-objectives" aria-label="Permalink to &quot;3.46.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand power transmission mechanics in compound gear trains, superimposing concurrent swinging and rotational motion. Master collaborative control methods for dual-servo synchronized oscillation. Understand correlations between motor speed settings and actual rotational velocity. Explore design logic using alternating RGB lighting to build thematic atmospheric tension.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the complex mechanical structure of the thrill pendulum ride independently, mastering dual-servo zero-point calibration during installation. Construct basic compound-motion routines coordinating dual-servo synchronized swinging with motor rotation. Implement an integrated routine combining swinging, spinning, alternating red and blue RGB illumination, and dot matrix graphic displays.</p></li><li><p><strong>Thinking Objectives</strong>: Build system thinking for multi-degree-of-freedom composite motion, understanding kinematic superposition of rotation and oscillation. Develop programming methodologies for dual-actuator synchronized control. Strengthen creative design capabilities for multi-sensory thematic environments.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to amusement park attractions including pendulum rides, Ferris wheels, and spinning swing rides. Understand the engineering applications of multi-degree-of-freedom mechanisms in amusement ride design. Inspire exploration into theme park engineering, ride attraction design, and creative mechanical automation.</p></li></ol><h2 id="_3-46-3-preparation" tabindex="-1">3.46.3 Preparation <a class="header-anchor" href="#_3-46-3-preparation" aria-label="Permalink to &quot;3.46.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>180° block servo</p></li><li><p>360° block motor</p></li><li><p>RGB light module</p></li><li><p>Dot matrix module</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab graphical programming platform</li></ul><h2 id="_3-46-4-hands-on-project" tabindex="-1">3.46.4 Hands-On Project <a class="header-anchor" href="#_3-46-4-hands-on-project" aria-label="Permalink to &quot;3.46.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the Thrill Pendulum Ride, delivering a dynamic amusement experience that superimposes rotation, oscillation, and chromatic lighting. The system adopts an architecture combining dual-servo swinging, motor rotation, and atmospheric audiovisual effects. Dual servos oscillate synchronously between 50° and 130°, while a motor drives the entire assembly to spin continuously, superimposing their motion into a complex spiral trajectory. The RGB module flashes between red and blue while the dot matrix module renders thematic graphics, reinforcing an atmospheric environment. Once activated, rotation and swinging operate concurrently while audiovisual elements synchronize with the rhythm, authentically recreating the dynamic thrill of a giant pendulum ride.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),w(a,{src:"../../_static/shared/pdf/chapter_3/46.pdf"}),e[1]||(e[1]=n('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the left 180° block servo to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the right 180° block servo to port <strong>S2</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the 360° block motor to port <strong>S3</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the dot matrix module to the RGB light module using a 4-pin module cable, then connect the assembly to port <strong>A</strong> of the controller using another 4-pin module cable.</p></li></ul><img loading="lazy" height="1887" width="3010" src="'+v+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>180° servo</strong> and <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+x+'" class="common_img" style="width:800px;"><ul><li>Select <strong>Dot matrix module</strong> and <strong>RGB module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+k+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="121" width="358" src="'+s+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+i+'"></td><td style="text-align:left;">Serve as the main program loop container, continuously executing internal code after power-on initialization.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="111" width="360" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+i+'"></td><td style="text-align:left;">Execute only once after startup to initialize hardware configurations and system parameters.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="145" width="655" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+o+'"></td><td style="text-align:left;">Drive the 360° block motor at a designated port to rotate continuously at a customized speed in the forward or reverse direction.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="88" width="708" src="'+c+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+o+'"></td><td style="text-align:left;">Control the 180° block servo at the designated port to rotate for a specified duration at a customized speed. In non-blocking mode, the program proceeds immediately to subsequent blocks without waiting for motion completion.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="290" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+t+'"></td><td style="text-align:left;">Adjust the backlight brightness of the dot matrix screen at the designated port across a range of 1 to 8, with higher values providing brighter illumination.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="64" width="280" src="'+m+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+t+'"></td><td style="text-align:left;">Control the dot matrix module at the designated port to load and display preset graphic patterns.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="64" width="414" src="'+p+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+t+'"></td><td style="text-align:left;">Control the RGB light module at the designated port to illuminate in preset colors.</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="251" width="431" src="'+P+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>Upon startup, the program initializes the brightness of the dot matrix screen, establishing the initial state of the ride. In the main loop, motor S3 rotates forward at 30% speed to spin the ride structure, and servos S1 and S2 oscillate repeatedly between 130° and 50° at 10% speed to swing the pendulum arm. Concurrently, the RGB light module alternates synchronously between red and blue, and the dot matrix module displays alternating checkmark and cross patterns.</p></li></ul><img loading="lazy" height="830" width="627" src="'+z+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to complete the program transfer and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+g+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1adJTOnyve2MmEehrB9YFSW8echTWwoF2?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-46-5-expansion-and-challenge" tabindex="-1">3.46.5 Expansion and Challenge <a class="header-anchor" href="#_3-46-5-expansion-and-challenge" aria-label="Permalink to &quot;3.46.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Progressive Acceleration Pendulum Ride</strong></p><p>Increment motor rotation speed and expand servo swinging angles upon each completed oscillation, gradually ramping up to full-speed, maximum-amplitude operation. Practice dual-parameter dynamic modulation and progressive attraction profiling while understanding safety considerations in ride acceleration. Extend discussions to roller coaster lift hill mechanics and gradual acceleration staging in large-scale park attractions.</p><p><strong>Project 2: Audio-Enhanced Thematic Pendulum Ride</strong></p><p>Integrate a buzzer to play low-pitch ambient tones, raising the audio pitch when the pendulum reaches peak elevation to heighten dramatic tension alongside synchronized lighting and pattern shifts. Practice audio-kinetic synchronization and multi-sensory immersive attraction design. Extend discussions to themed dark rides, four-dimensional theater effects, and virtual reality amusement simulations.</p><h2 id="_3-46-6-q-a" tabindex="-1">3.46.6 Q&amp;A <a class="header-anchor" href="#_3-46-6-q-a" aria-label="Permalink to &quot;3.46.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Why does the thrill pendulum ride require two servos rather than a single servo to drive oscillation?</strong></p><p>Answer: Dual servos provide <strong>structural force balance and smooth swinging locomotion</strong>. The pendulum arm spans horizontally across two side supports. If only a single servo powers one side while the opposite side remains unpowered, force applies unevenly across the structural span. This torque asymmetry causes mechanical binding, wobbling, and excessive torsional strain on the drive shaft. Installing independent servos on both sides to drive the arm synchronously distributes structural loads evenly across both pivot points. This arrangement delivers smooth, balanced oscillation without jamming, while providing combined torque capable of swinging heavier payloads. Both servos must maintain precise synchronization, matching identical rotation angles and velocities. In mechanical engineering, this concept is known as dual-drive synchronization. It serves widely in high-load and wide-span applications, including industrial overhead gates, scissor lifts, and movable bridge spans, ensuring balanced operational stability.</p><p><strong>Question 2: How does the thrill pendulum ride execute concurrent rotation and swinging smoothly without mechanical interference?</strong></p><p>Answer: The system relies on <strong>two independent transmission drivetrains operating concurrently without mutual interference</strong>. Rotation represents one drivetrain: motor S3 drives the entire support assembly and pendulum arm through gears, producing collective revolution around the central vertical axis. Swinging represents an independent drivetrain: dual servos directly oscillate the crossbeam, producing localized angular swing. These two drivetrains remain mechanically decoupled: the motor rotates the primary structure while the servos oscillate the pendulum arm, combining seamlessly through a compound gear assembly without cross-torque interference. Software routines also manage these operations independently. Once commanded to start, the continuous motor runs uninterrupted, while the servo routine executes an ongoing oscillation loop. Operating both routines concurrently produces a composite kinematic motion. The physical superposition of circular rotation and vertical swinging generates a complex three-dimensional helical trajectory, delivering an engaging multi-axis experience that surpasses simple single-axis swinging.</p><h2 id="_3-46-7-technical-support-and-product-discussion" tabindex="-1">3.46.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-46-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.46.7 Technical Support and Product Discussion&quot;">​</a></h2><p>Submit questions or share project modifications in the community forum:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+u+'" class="common_img" style="width:800px;"></a>',31))])}const Q=y(q,[["render",T]]);export{M as __pageData,Q as default};
